import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch BE everyday-crime stories.
extension FollowUpCases {
    static let batchBE: [CaseTemplate] = [ringsAgain, sergeantAgain, clerkAgain, alibiAgain, witnessPayAgain, jurorAgain, logAgain, kidnapReportAgain, swatAgain, jamAgain, dragAgain, footChaseAgain, chaseKidsAgain, truckDeathAgain, raceAgain2, crosswalkAgain, minivanAgain, seventhDwiAgain, revokedCyclistAgain, brakeAgain, scaffoldAgain, dogsAgain, kennelAgain, warehouseAgain, carBurnAgain, stillAgain, scrapCableAgain, poisonAgain, puppyAgain, bearAgain, barShootAgain, trailerShootAgain, overlookShotAgain, hallDebtAgain, driveByAgain, schoolGunAgain, teenGunAgain]

    static let ringsAgain = SmallCases.make(
        key: "story.followup.ringsAgain",
        category: .property,
        headlines: ["Embalmer at Second Funeral Home Linked to Missing Jewelry", "Prior Funeral Worker Case Linked to New Home"],
        law: "felonyLarceny",
        spec: "Took and carried away property of {V} and others valued at $4,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, three families at another funeral home found jewelry missing. {D} sold gold at a shop. {DL} says it was family gold.",
        state: [E(.document, 3, "Gold Shop Records", "{D} sold gold."), E(.document, 2, "Family Reports", "Rings missing.")],
        defense: [E(.statement, 1, "Family Gold", "{DL} says it was family gold.")],
        role: "Funeral director",
        exam: [.direct("Please tell the jury about your work.", "\"I'm a funeral director with more than twenty years in the business. I prepare the deceased, meet with families and run the services at our chapel.\""), .direct("What did the families report to you?", "\"Three families called within a week. Each said a ring or a piece of jewelry that their loved one had been wearing at the visitation was missing afterward.\""), .direct("How do you handle jewelry on the deceased?", "\"We list every piece on an intake sheet and the family signs it. At the end, we return it in a sealed envelope or leave it in place.\""), .direct("What did you find when you checked your records?", "\"For all three, the intake sheet listed the jewelry, and the envelope or the body no longer had it. I compared the dates and the staff who had access.\""), .direct("What did the gold shop records show?", "\"{D} sold gold to a local shop during that same week, in several small lots. The shop recorded {D.his} identification each time.\""), .direct("What did the three families lose?", "\"Wedding bands, a pendant and a few smaller pieces. The total value was about $4,000, and some of it was sentimental and can't be replaced.\""), .cross("Did you see {DL} take any jewelry from any of the deceased?", "\"No, I did not. I only know what the intake sheets and the shop records show.\""), .cross("Do the shop records identify any of the three families' pieces by description?", "\"Not by any family's name. They list weights and a general description of the gold.\""), .cross("How many staff and visitors had access to the viewing room?", "\"Several, over the week. Staff, a few volunteers and visiting family members could all have been there.\""), .cross("Did {DL} work at your funeral home?", "\"No. {D.He} worked at a different funeral home, and {D.he} never worked here.\""), .cross("Can you tell the jury that any item {DL} sold came from your chapel?", "\"No. I can't tie any of the sold pieces to the three families.\"")],
        theory: ("{D} took rings and other jewelry from the dead at a second funeral home and sold the gold at a shop.", "The gold {D} sold was family gold inherited from {D.his} own people, not jewelry taken from anyone's loved one."),
        allocution: "\"I'm sorry to those three families. The gold I sold at that shop was mine, family gold from my own people, and I never took anything from anyone's loved one. I've been in this courtroom before about a funeral home, and I know how that looks. I hope the court considers what I can prove.\"",
        truths: ("Three families reported jewelry missing after services at the funeral home, and {DL} sold gold at a shop that week.", "{DL} inherited jewelry from {D.his} family and had receipts and photos showing the pieces were {D.his} own."),
        defendant: [.direct("Did you take jewelry from the deceased at the funeral home?", "\"No, I never took a thing from anyone's loved one. I would never do that, and I'm sorry those families lost anything.\""), .direct("What did you sell at the gold shop?", "\"Pieces of gold that belonged to my own family, which I inherited. Some were rings and chains from my grandmother and my aunt.\""), .direct("Can you show where the gold came from?", "\"I have photos of my grandmother wearing the pieces, and a will that lists them. I gave copies to the deputies.\""), .direct("Why did you sell the gold when you did?", "\"I'd fallen behind on bills, and gold prices were high that month. It seemed like the sensible thing to sell what I'd inherited.\""), .direct("What do you do at your own funeral home?", "\"I'm a director too, at a different home. I know how much families trust us, and I'd never betray that.\""), .direct("How did you feel when you heard about the three families?", "\"Sick for them. I know what it's like to bury someone, and I'd never want a family to feel they were robbed.\""), .cross("You have been in this court before about a funeral home, haven't you?", "\"Yes, I was, and I understand why that makes people look twice at this. This time the gold I sold was my own.\""), .cross("You sold gold in the same week that the jewelry went missing, didn't you?", "\"Yes, and I understand why that stands out. It was a coincidence, driven by my bills.\""), .cross("You had access to funeral homes and the deceased, didn't you?", "\"Yes, in my own work. I'd never been inside that chapel.\""), .cross("The shop recorded several small lots of gold, didn't it?", "\"Yes, because I sold a few pieces at a time to get a better price.\""), .cross("You can't prove every piece you sold was inherited, can you?", "\"I can show photos and a will for most of them. I'll gladly give the court every document I have.\"")],
        openings: ("Three families who held services at a funeral home found jewelry missing from their loved ones, worth about $4,000 together. Gold shop records show {D} sold gold that same week, and {DL} came through this court in {PRIORDATE} in the file for {PRIOR}.", "{DL} says the gold was family gold inherited from {D.his} own people. The defense will show that nothing ties {D.his} pieces to any of the three families."),
        closings: ("Three families lost rings and jewelry to a place they trusted, and {D} sold gold at a shop within days. This is not {DL}'s first time here, since {PRIORDATE} brought {D.him} in once already for {PRIOR}. The records line up too closely to ignore.", "The State has a sale of gold and three grieving families, but nothing that connects the two. {D} inherited that gold, and a gold sale is not proof of taking anything from the dead."),
        timeline: [(-7, "Three families hold services at the funeral home."), (0, "The families find rings and jewelry missing from their loved ones."), (3, "{D} sells gold at a local shop and deputies obtain the shop's records.")],
        identified: "Gold Shop Records",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction)

    static let sergeantAgain = SmallCases.make(
        key: "story.followup.sergeantAgain",
        category: .whiteCollar,
        headlines: ["Lieutenant Took Cash to Void Citations", "Prior Police Bribery Case Linked to New Department"],
        law: "bribery",
        spec: "Corruptly accepted a thing of value as a public official, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}, a lieutenant at another agency, took $300 to void citations. {DL} says it was a loan repayment.",
        state: [E(.video, 3, "Recording", "An envelope passes."), E(.document, 2, "Ticket Records", "Citations voided.")],
        defense: [E(.statement, 1, "Loan", "{DL} says it was a loan.")],
        role: "SBI agent",
        exam: [.direct("Please tell the jury about your work.", "\"I'm an agent with the State Bureau of Investigation. I investigate public corruption, and I get cases when officials are suspected of taking money for official favors.\""), .direct("How did this investigation begin?", "\"A person with several traffic citations told us that a lieutenant had offered to void them for cash. We set up a recorded meeting.\""), .direct("What does the recording show?", "\"The person hands {D} an envelope in a parking lot, and {D.he} takes it, looks inside and puts it in a jacket pocket.\""), .direct("What did the envelope contain?", "\"$300 in cash, as counted by our agents. The bills were photocopied before the meeting.\""), .direct("What happened to the citations?", "\"Ticket records show that within the week, several of that person's citations were voided in the system from {D.his} login.\""), .direct("Who is {DL}?", "\"{D.He} is a lieutenant at another agency, and {D.he} had supervisory access to void tickets for that agency.\""), .cross("Did the recording include any words about voiding tickets?", "\"There was some conversation I'd have to replay. I don't recall an explicit agreement on tape.\""), .cross("Did {DL} say anything about a loan?", "\"Yes, {D.he} said the envelope was repayment of money {D.he} had lent.\""), .cross("Is there a note about the loan?", "\"I've since seen a handwritten note that refers to a loan. I haven't verified its date.\""), .cross("Could a supervisor void tickets for legitimate reasons?", "\"Yes. A lieutenant may void a citation for an error or a clear reason.\""), .cross("Do the ticket records say why each citation was voided?", "\"The system lists a reason code. I'd have to look at them one by one.\"")],
        theory: ("{D}, a lieutenant at another agency, took $300 in an envelope in exchange for voiding citations.", "The money was repayment of a loan, and {DL} never voided any citation for pay."),
        allocution: "\"That three hundred dollars was repayment of a loan, and I believed it was only that. I've been in this courtroom before as an officer, and I know how it appears. I never meant to void any citations for money, and I'll cooperate with any review.\"",
        truths: ("A recording shows an envelope passing, and the citations were voided in the same week.", "A handwritten note shows {DL} had lent the money earlier, and the envelope was the repayment."),
        defendant: [.direct("Did you take the envelope with $300?", "\"Yes, I did. It was repayment of a loan I'd made to that person months before.\""), .direct("Can you describe the loan?", "\"I lent about $300 to help with rent. We wrote a short note, and the person promised to pay me back when work picked up.\""), .direct("Did you void any citations in return?", "\"No. Any citations that were voided were handled for legitimate reasons. I never connected them to the money.\""), .direct("Why did you meet in a parking lot?", "\"It was convenient for both of us. The person asked to repay in cash, and I agreed.\""), .direct("What did you do with the money?", "\"I put it in my pocket and deposited it later. I've kept my bank records.\""), .direct("How do you feel about the allegation?", "\"I'm angry and sad. I've worked in law enforcement for a long time, and I'd never sell my badge.\""), .cross("You have been in this court before as an officer, haven't you?", "\"Yes, and I know how that appears. This time it was a loan.\""), .cross("The citations were voided the same week, weren't they?", "\"Yes, and I understand how that looks. It was a coincidence.\""), .cross("You had access to void tickets, didn't you?", "\"Yes, as a supervisor. I used that access only for valid reasons.\""), .cross("You accepted cash in an envelope, didn't you?", "\"Yes, as repayment, and I didn't count it.\""), .cross("Your note about the loan isn't dated, is it?", "\"It's dated, I believe, but I'll have to check my copy.\"")],
        openings: ("A lieutenant at another agency took an envelope with $300 from a person with several citations, and those citations were voided in the same week. A recording captured the envelope changing hands, and Court records have {DL} here before, in {PRIORDATE} over {PRIOR}.", "{DL} says the envelope was repayment of a loan {D.he} made months earlier, and a handwritten note shows the loan. The defense will show a personal debt, not a payoff."),
        closings: ("An envelope with $300 passed to {D}, and several citations vanished from the ticket system in the same week. The recording and the ticket records fit together. {DL} first appeared on this court's docket in {PRIORDATE} for {PRIOR}.", "A handwritten note shows {D} had lent that money earlier. A repayment is not a bribe, and the State has not shown that {DL} ever voided a ticket for pay."),
        timeline: [(-90, "{D} lends $300 to an acquaintance who later has several citations."), (0, "A recording shows an envelope passing to {D}."), (3, "Ticket records show the citations voided.")],
        identified: "Recording",
        mood: .wantsConviction)

    static let clerkAgain = SmallCases.make(
        key: "story.followup.clerkAgain",
        category: .whiteCollar,
        headlines: ["Magistrate's Clerk Took Cash to Skip Hearings", "Prior Clerk Bribery Case Linked to New Office"],
        law: "bribery",
        spec: "Corruptly accepted a thing of value as a public official, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}, a clerk in another office, took $700 to skip hearings. {DL} says people were paying fines.",
        state: [E(.document, 3, "Case Files", "Hearings skipped."), E(.digital, 2, "Deposit Slips", "$700 to {D}.")],
        defense: [E(.statement, 1, "Fines", "{DL} says the cash was fines.")],
        role: "Clerk of court",
        exam: [.direct("Please tell the jury about your role.", "\"I'm the clerk of court in this county. I supervise the office that keeps case files, schedules hearings and receives fines and fees.\""), .direct("How did you learn about {D}?", "\"An audit of another county's office flagged a number of hearings that were skipped without a judge's order. {DL} was a clerk there.\""), .direct("What did the case files show?", "\"Several cases had their hearings marked as skipped, with no judge's signature. The people involved had all paid cash around that time.\""), .direct("What did the deposit slips show?", "\"$700 deposited in a way that traced back to {DL}, and not through the office's normal receipt book.\""), .direct("How are fines supposed to be handled?", "\"Every payment is entered in the system and a receipt is written. The cash goes in the drawer and is deposited by the end of the next business day.\""), .direct("What did you conclude?", "\"That hearings were skipped and money was taken in the same weeks, and there was no entry showing an official reason.\""), .cross("Did {DL} ever enter any of the payments in the system?", "\"Some of them, yes. I'd have to check the full list.\""), .cross("Do clerks sometimes take fine payments at the window?", "\"Yes. That's one of their regular duties.\""), .cross("Did {DL} issue receipts?", "\"For some payments, yes. For others, I haven't found one.\""), .cross("Does a clerk have authority to skip a hearing?", "\"No, only a judge can. A clerk can only schedule, not skip.\""), .cross("Did anyone say {DL} promised to skip a hearing for money?", "\"No one has said that to me directly.\"")],
        theory: ("{D}, a clerk in another office, took $700 in cash to have hearings skipped.", "The $700 was fines that people paid at {D.his} window, and {DL} treated it as ordinary payments."),
        allocution: "\"The seven hundred dollars I took in was fines that people were paying at my window, and I treated it that way. I've been in this courtroom before about my work, and I should have been more careful with the receipts. I'm sorry for the confusion, and I'll account for every dollar.\"",
        truths: ("Case files show hearings skipped and deposit slips show $700 to {D}.", "{DL} took fine payments at the window as part of the job, and receipts were written for most of them."),
        defendant: [.direct("Did you take $700 in cash from people with hearings?", "\"I took payments of fines at my window. That's part of my job, and I treated them as ordinary payments.\""), .direct("How did you handle those payments?", "\"I wrote receipts for most of them and entered them in the system. A few I put in the drawer to enter later, and I lost track.\""), .direct("Did you skip any hearings in exchange for money?", "\"No. I don't have the authority to do that, and I never told anyone that I could.\""), .direct("Why were some hearings marked skipped?", "\"I may have clicked the wrong button when a person paid in advance and I thought the hearing wasn't needed. That was a mistake.\""), .direct("What did you do when the audit came?", "\"I answered every question and gave them my records. I've offered to account for every dollar.\""), .direct("How do you feel about it?", "\"Awful. I've worked in the court system for many years, and I never wanted to cause confusion.\""), .cross("You have been in this court before about your work, haven't you?", "\"Yes, and I should have been more careful with the receipts. I'm sorry.\""), .cross("Some of the payments don't have receipts, do they?", "\"Right, a few don't, and that's a failure of mine.\""), .cross("The hearings were marked skipped under your login, weren't they?", "\"Yes, they were, and I take responsibility for that.\""), .cross("You had no authority to skip hearings, did you?", "\"No, I did not, and I never claimed I did.\""), .cross("$700 in cash is not a small amount, is it?", "\"It's not, and I should have deposited it right away.\"")],
        openings: ("A clerk in another county office took $700 from people with pending cases, and the case files show their hearings were skipped. Deposit slips show the money went to {D}, and The court file shows {DL} here in {PRIORDATE} in the case known as {PRIOR}.", "{DL} says the cash was fines that people were paying at {D.his} window, and {D.he} treated them as ordinary payments. The defense will show that taking fines is part of a clerk's job, and nothing shows that {D.he} traded money for a skipped hearing."),
        closings: ("Hearings were skipped, and $700 landed in {D}'s hands in the same weeks. The files and the deposit slips tell the story. {DL} was last before this court in {PRIORDATE} in connection with {PRIOR}. A clerk is trusted to keep the court's business honest.", "Taking payments at a window is a clerk's job. The $700 was fines, with receipts for most of it. The State has shown cash and skipped hearings, but not one agreement that connected them."),
        timeline: [(-14, "Several people have hearings scheduled in {D}'s office."), (0, "People pay cash at {D}'s window, and the hearings are marked skipped."), (7, "An audit finds the skipped hearings and $700 in deposit slips to {D}.")],
        identified: "Case Files",
        mood: .wantsConviction)

    static let alibiAgain = SmallCases.make(
        key: "story.followup.alibiAgain",
        category: .publicOrder,
        headlines: ["Aunt Lied Under Oath to Give Nephew an Alibi", "Prior Alibi Perjury Case Linked to New Trial"],
        law: "perjury",
        spec: "Willfully made a false statement under oath in a judicial proceeding, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} testified that a nephew was home all night. His phone showed him across town. {DL} says the phone was elsewhere.",
        state: [E(.document, 3, "Transcript", "'He was home all night.'"), E(.digital, 2, "Phone Records", "Phone across town.")],
        defense: [E(.statement, 1, "Phone Left", "{DL} says the phone was left elsewhere.")],
        role: "Court reporter",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a court reporter. I take down every word spoken in the courtroom and prepare a transcript that is the official record of the proceeding.\""), .direct("What did the transcript show about {D}'s testimony?", "\"{DL} was sworn and said, 'He was home all night,' about a nephew. I read it back from my notes when the trial resumed.\""), .direct("Was {DL} sworn before testifying?", "\"Yes. {DL} took the oath and said {D.he} understood it, and I recorded it.\""), .direct("Did {DL} repeat the statement on cross-examination?", "\"Yes. {D.He} said it again when asked, in nearly the same words.\""), .direct("What was the context of that testimony?", "\"It was in a criminal trial about a break-in. The nephew was the defendant, and the time of the offense was in the middle of the night.\""), .direct("How do you know the transcript is accurate?", "\"I certify it, and I compare my notes against the audio record. I'm required to correct any error before I sign.\""), .cross("Did {DL} say the nephew never left the house?", "\"{D.He} said he was home all night. {D.He} didn't use the word never.\""), .cross("Did {DL} say how {D.he} knew the nephew was home?", "\"{D.He} said {D.he} saw the nephew go to bed and heard him in the house.\""), .cross("Did {DL} ever mention the nephew's phone?", "\"No. The phone didn't come up in {D.his} testimony.\""), .cross("Do you have any knowledge of where the nephew was that night?", "\"No. I only record testimony. I know nothing beyond that.\""), .cross("Is it unusual for a witness to be mistaken about the exact hours?", "\"Not at all. Witnesses misremember times and details often.\"")],
        theory: ("{D} swore at a trial that a nephew was home all night, when the nephew's phone showed {D.him} across town.", "{DL} testified to what {D.he} believed, and the nephew's phone was left somewhere else."),
        allocution: "\"I testified to what I believed, that my nephew was home all night. His phone may have been elsewhere, but I thought he was in the house. I've been in this courtroom before, and I'd never knowingly lie under oath. I'm sorry if I was wrong, and I love my family.\"",
        truths: ("The transcript has {DL} swearing 'He was home all night,' and phone records place the nephew's phone across town.", "A friend confirms the phone was left at another location, and the nephew was at home."),
        defendant: [.direct("Did you swear that your nephew was home all night?", "\"Yes, I did. I said it because I believed it. I saw him go to bed, and I heard him in the house.\""), .direct("How do you know he was home?", "\"He lives in my house, and I saw him go to his room that night. I heard the television and then the door close.\""), .direct("Did you know where his phone was that night?", "\"No. I never thought about his phone, and I never knew it was elsewhere until the records came out.\""), .direct("How could the phone be across town?", "\"My nephew has a habit of leaving his phone with a friend. A friend has told me that happened that night.\""), .direct("Did you lie under oath?", "\"No. I told the court exactly what I believed was true. I would never knowingly lie under oath.\""), .direct("How do you feel about the charge?", "\"Hurt and confused. I love my family, and I only wanted to tell the truth about what I saw.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I'd never knowingly lie under oath. I know how it looks.\""), .cross("You were asleep at some point that night, weren't you?", "\"Yes, for a few hours. I can't be sure what happened then.\""), .cross("The phone records show your nephew across town, don't they?", "\"They show his phone, and I don't know whether he was with it.\""), .cross("You want to protect your nephew, don't you?", "\"I do, but I'd never lie for him. I told the truth as I knew it.\""), .cross("You swore that he was home all night, didn't you?", "\"Yes, and I believed it.\"")],
        openings: ("At a trial, {D} swore under oath that a nephew was home all night. The court reporter's transcript has the exact words, and phone records show the nephew's phone across town. {DL} was already known to this court from {PRIORDATE} in a matter involving {PRIOR}.", "{DL} says the nephew was in the house, and the phone was left somewhere else. A friend confirms the phone was not with the nephew, and the defense will show an honest belief."),
        closings: ("The transcript has {D} swearing 'He was home all night,' and the phone records say otherwise. {DL} was no stranger to this courtroom after {PRIORDATE} on a charge of {PRIOR}. A false statement under oath strikes at the court itself.", "{D} testified to what {D.he} believed. A friend confirms the phone was left elsewhere, and a phone is not a person. The State has not shown that {DL} knew the testimony was false."),
        timeline: [(-30, "A nephew is charged, and {D} agrees to testify."), (0, "{D} swears that the nephew was home all night."), (5, "Phone records place the nephew's phone across town that night.")],
        identified: "Transcript",
        mood: .sympathetic,
        genders: ["D": .female])

    static let witnessPayAgain = SmallCases.make(
        key: "story.followup.witnessPayAgain",
        category: .violent,
        headlines: ["Defendant's Cousin Pays Witness to Skip Court", "Prior Witness-Pay Case Linked to New Trial"],
        law: "witnessIntimidation",
        spec: "Attempted to deter a witness from testifying by offering a thing of value, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sent $600 to a witness before trial. {DL} says it was a loan.",
        state: [E(.digital, 3, "Payment App", "$600 to {V}."), E(.digital, 2, "Messages", "'Be gone Friday.'")],
        defense: [E(.statement, 1, "Loan", "{DL} says it was a loan.")],
        role: "Witness",
        exam: [.direct("Please tell the jury how you came to know {D}.", "\"I know {DL} from the neighborhood. I'm also a witness in a case against {D.him}, and I was expected to testify at trial.\""), .direct("What did you receive from {DL}?", "\"$600 through a payment app, a few days before the trial. It came with a message that said 'Be gone Friday.'\""), .direct("How did you understand the message?", "\"As a signal to leave town before the trial began. I took it to mean I should not testify.\""), .direct("What did you do?", "\"I took a screenshot and called the sheriff's office. I didn't spend any of the money.\""), .direct("Had you and {DL} spoken before about money?", "\"We had, a long while back. I had lent {D.him} small sums a few times, never anything near $600, and I'd never asked for any of it back.\""), .direct("How did the message and the money make you feel?", "\"Scared. I thought {D.he} was trying to get me to leave, and I was worried about what would happen if I didn't.\""), .cross("Did you lend {DL} money in the past?", "\"Yes, a few times, small amounts, and never anything near $600.\""), .cross("Did {DL} say what the $600 was for?", "\"Only in a message that said it was for what was owed.\""), .cross("Could 'Be gone Friday' refer to something else?", "\"It could, but I didn't know what else it would mean.\""), .cross("Did {DL} threaten you?", "\"No. There was no threat in the message.\""), .cross("Did you give the money back?", "\"Yes, to the deputies, when they asked.\"")],
        theory: ("{D} sent a witness $600 before trial and told {V.him} to be gone by Friday.", "The $600 was repayment of a loan, and the message was only a note about timing."),
        allocution: "\"The six hundred dollars I sent that witness was a loan, and I told them so. I've been in this courtroom before, and I know how sending money before trial looks. I'm sorry if it caused alarm. I'll cut off all contact until the case is done.\"",
        truths: ("The payment app shows $600 to {V}, and a message reads 'Be gone Friday.'", "A prior loan existed between {DL} and {V}, and the $600 repaid it."),
        defendant: [.direct("Did you send {V} $600 before the trial?", "\"Yes, I did. It was repayment of a loan {V.he} made me months ago, and I told {V.him} that in the message.\""), .direct("What did the loan cover?", "\"A car repair when I was short. {V.He} lent me the money and said I could pay it back when I could.\""), .direct("What did you mean by 'Be gone Friday'?", "\"I meant that the debt would be gone by Friday, once I paid it off. I wrote it fast and it was worded badly.\""), .direct("Why did you send it just before the trial?", "\"I got paid that week, and I wanted to clear the debt. I didn't think about the timing.\""), .direct("Did you ask {V.him} not to testify?", "\"No. I never mentioned the trial. I only sent the money and the message about the debt.\""), .direct("What will you do now?", "\"I'll cut off all contact until the case is done. I know how it looked, and I'm sorry if it caused alarm.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know sending money before a trial looks bad.\""), .cross("{V} was a witness in your case, wasn't {V.he}?", "\"Yes, and I should have waited to repay.\""), .cross("Your message said 'Be gone Friday,' didn't it?", "\"Yes, and I see how that could be read.\""), .cross("You sent $600 days before the trial, didn't you?", "\"Yes. I wired it from my phone the week before, because I wanted to make it right and did not think about what it would look like.\""), .cross("You didn't mention a loan in the message, did you?", "\"I did, in the line before.\"")],
        openings: ("A witness in {D}'s case received $600 through a payment app, and a message said 'Be gone Friday,' days before trial. {DL} already has a history in this court, dating to {PRIORDATE} on the earlier matter, {PRIOR}.", "{DL} says the $600 was repayment of a loan, and the message was only about a timing detail. The defense will show a prior loan and a message that does not tell anyone to skip court."),
        closings: ("A witness got $600 and a message saying 'Be gone Friday' days before trial. {D} had every reason to want the witness absent. Back in {PRIORDATE}, {DL} was a defendant in this court on a charge of {PRIOR}. Paying a witness to stay away is witness tampering.", "{D} owed {V} money from an earlier loan and repaid it. The message was about clearing a debt, not about leaving court. The State has put two facts side by side, and has not proved they are related."),
        timeline: [(-60, "{V} lends money to {D}, who agrees to repay it later."), (-4, "{D} sends $600 and a message about Friday through a payment app."), (0, "{V} reports the payment and message to deputies before the trial.")],
        identified: "Payment App",
