    static let kennelAgain = SmallCases.make(
        key: "story.followup.kennelAgain",
        category: .violent,
        headlines: ["Boarding Stable Burned With Horses Inside", "Prior Kennel Fire Owner Linked to Stable Fire"],
        law: "burningBuildings",
        spec: "Willfully and maliciously burned a stable owned by {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a boarding stable burned overnight, killing four horses. {D} had raised insurance. {DL} says wiring failed.",
        state: [E(.forensic, 3, "Fire Report", "Two ignition points."), E(.document, 2, "Policy Change", "Coverage raised.")],
        defense: [E(.statement, 1, "Wiring", "{DL} says wiring failed.")],
        role: "Fire marshal",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a fire marshal. I investigate the cause of fires, determine where and how they started and decide whether they were accidental or set.\""), .direct("What did you find at the stable?", "\"The roof had collapsed and the building was a total loss. Four horses died, and the rest were removed safely.\""), .direct("What did your investigation show about the origin?", "\"There were two separate ignition points about forty feet apart, which is unusual for an accidental fire.\""), .direct("What did you find about the wiring?", "\"Some of the wiring was damaged by the fire, but I could not rule out an electrical cause for one of the points. The second looked different.\""), .direct("What was in {D}'s policy?", "\"Coverage was raised about six weeks before the fire. {D.He} told the agent that {D.he} had added horses.\""), .direct("How did the horses die?", "\"Smoke inhalation, mostly. They were stalled and could not get out in time.\""), .cross("Did an electrician look at the stable earlier?", "\"A report I received notes faults in the wiring a few months before the fire.\""), .cross("Did {DL} add horses to the stable before the policy change?", "\"Yes. Records show that horses were added in the weeks before.\""), .cross("Was accelerant found?", "\"No. The lab found no trace of an accelerant.\""), .cross("Did {DL} try to save the horses?", "\"Yes. {D.He} ran in and let several out before the heat drove {D.him} back.\""), .cross("Were the two ignition points certain?", "\"They were what I judged from burn patterns. They are my opinion, not a lab result.\"")],
        theory: ("{D} set fire to a boarding stable overnight, killing four horses, after raising {D.his} insurance coverage.", "Faulty wiring started the fire, and {DL} raised coverage because {D.he} had added horses."),
        allocution: "\"The wiring in that stable was faulty, and I never set that fire. I raised my insurance because I'd added horses, and I loved them. I've been in this courtroom before about a barn, and I know how it looks. I'm heartbroken about the four horses.\"",
        truths: ("The fire report found two separate ignition points, and the policy change came weeks before.", "An electrician had noted wiring faults in the stable, which fits an electrical fire."),
        defendant: [.direct("Did you set the fire at your stable?", "\"No. I never set that fire, and I'd never harm my horses. I loved them.\""), .direct("Why did you raise your insurance?", "\"Because I'd added horses, and the old coverage no longer covered them. My agent recommended it.\""), .direct("What do you know about the wiring?", "\"An electrician told me that the wiring needed repair. I was saving up to have it done.\""), .direct("What did you do when the fire started?", "\"I ran in and let out as many horses as I could. The heat got too bad, and I couldn't save the last four.\""), .direct("How did you feel about it?", "\"Heartbroken. Those horses were part of my family. I still dream about that night.\""), .direct("What do you want to say to the court?", "\"I loved those horses, and I'd give the insurance money back to have them again.\""), .cross("You have been in this court before about a barn, haven't you?", "\"Yes, I was here before about a barn, and I know how it looks when it happens a second time. I'm telling the truth.\""), .cross("You raised your insurance six weeks before the fire, didn't you?", "\"Yes, I raised it about six weeks before, but only because I had added horses and the old coverage wouldn't have paid for them.\""), .cross("The wiring was faulty and you hadn't repaired it, had you?", "\"Not yet. The electrician told me it needed work, and I was saving up to pay for it, and I wish I had done it sooner.\""), .cross("There were two ignition points, weren't there?", "\"That's what the marshal says, and I can't explain it. I know that wiring in an old stable can fail in more than one place.\""), .cross("You stood to collect on the policy, didn't you?", "\"Yes, I would have collected on the policy, but I'd never harm my horses for money. I would give every dollar back to have them again.\"")],
        openings: ("A boarding stable burned overnight and four horses died. The fire marshal found two separate ignition points, {D} had raised the stable's insurance coverage weeks earlier. It was {PRIORDATE} when {DL} first came before this court over {PRIOR}.", "{DL} says the wiring in the stable was faulty and started the fire. An electrician had noted faults, and the defense will show that the coverage was raised because {D.he} had added horses."),
        closings: ("Two ignition points, a stable full of horses and a recent jump in insurance coverage. {D} stood to gain, and four horses died. The court file shows {DL} here in {PRIORDATE} in a case for {PRIOR}.", "The wiring in that stable was faulty, as an electrician noted before the fire. {D} raised coverage because {D.he} added horses, and {D.he} loved them. The State has not shown arson."),
        timeline: [(-30, "{D} raises the insurance coverage on the stable after adding horses."), (0, "Overnight: a fire breaks out in the stable and spreads quickly."), (0, "Firefighters arrive and four horses are found dead.")],
        identified: "Fire Report",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

