        exam: [.direct("Please tell the jury about your job.", "\"I'm a sheriff's deputy. I investigate thefts, and I serve warrants on properties where stolen goods may be kept.\""), .direct("What led you to the barn?", "\"Two tractors had been stolen from a farm supply dealer a few weeks earlier. A tip said they were at {D}'s barn.\""), .direct("What did you find?", "\"Two tractors with serial numbers that matched the stolen ones, covered with tarps. There was also a still in the back.\""), .direct("What was the value of the tractors?", "\"About $22,000 together. They were relatively new and in good condition.\""), .direct("Who owns the barn?", "\"The deed shows it belongs to {DL}, who lives in a house about two hundred yards away.\""), .direct("What did {DL} say?", "\"That a tenant had rented space for storage and paid cash. {D.He} said {D.he} never looked inside.\""), .cross("Did {DL} know the tractors were stolen?", "\"I can't say. {D.He} said {D.he} didn't.\""), .cross("Did the tenant have a name?", "\"{D.He} gave a first name, and we haven't been able to identify the person.\""), .cross("Did {DL} have a lease with the tenant?", "\"No. It was a verbal arrangement, and the rent was paid in cash.\""), .cross("Was the barn locked?", "\"The main door had a padlock. {D.He} had a key.\""), .cross("Did {DL} cooperate with the search?", "\"Yes. {D.He} opened the barn and answered my questions.\"")],
        theory: ("{D} kept two stolen tractors and a still in a barn {D.he} owns.", "A tenant stored the tractors and the still in the barn, and {DL} never looked closely."),
