    static let scrapCableAgain = SmallCases.make(
        key: "story.followup.scrapCableAgain",
        category: .property,
        headlines: ["Scrap Yard Bought Stolen Cable From Telecom Company", "Prior Scrap Yard Owner Linked to New Thefts"],
        law: "possStolen",
        spec: "Possessed stolen cable valued at $18,000, knowing it to be stolen, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a scrap yard owned by {D} bought $18,000 in cable stripped from a telecom depot. {DL} says sellers gave false names.",
        state: [E(.document, 3, "Weight Tickets", "Matching dates."), E(.physical, 2, "Cable", "Marked cable.", .search)],
        defense: [E(.statement, 1, "False Names", "{DL} says sellers gave false names.")],
        role: "Telecom security manager",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a security manager for the telecom company. I investigate thefts of cable and equipment from our depots and substations.\""), .direct("What was stolen from your depot?", "\"Large spools of copper cable that had been stripped of their insulation. The loss was about $18,000.\""), .direct("How did you find the cable?", "\"We marked our cable with a paint code, and one of our technicians saw marked cable at {D}'s scrap yard.\""), .direct("What did the weight tickets show?", "\"Sales to the yard on dates that match the thefts, in the same weights. The sellers were different each time.\""), .direct("What did the sellers' IDs show?", "\"Several different names, some of which turned out to be false. Deputies are still looking for them.\""), .direct("How much of the cable was recovered?", "\"Most of it, about $14,000 worth. The rest had already been sold on.\""), .cross("Did {DL} check the sellers' identification?", "\"Yes, the weight tickets list an ID for each seller, and the yard keeps a copy of each license. {D.He} did that every time.\""), .cross("Did some of the IDs turn out to be false?", "\"Yes, several of them turned out to be false. They were good fakes, and I'm not sure I would have caught them either.\""), .cross("Did {DL} report the sellers to anyone?", "\"Yes, {D.He} gave deputies the names, the descriptions and the license plates of the trucks the sellers drove.\""), .cross("Did {DL} cooperate in the recovery of the cable?", "\"Yes, {D.He} let us take back every foot of it without argument and even helped us load it onto our truck.\""), .cross("Was the cable obviously stolen when it arrived?", "\"Not obviously, no. Stripped cable looks like any other scrap copper, and a yard owner would not know where it came from.\"")],
        theory: ("{D} bought $18,000 worth of cable stripped from a telecom depot at a scrap yard, knowing it was stolen.", "Sellers gave false names, and {DL} checked the IDs and believed the cable was legitimate."),
        allocution: "\"I checked the IDs of everyone who sold me cable, but some gave false names. I've been in this courtroom before about my yard, and I know I'm responsible for what I buy. I'm sorry for the telecom's loss, and I'll tighten every procedure.\"",
        truths: ("Weight tickets match the dates of the depot thefts, and marked cable was found at {D}'s yard.", "{DL} reported the sellers to deputies after learning the cable was stolen."),
        defendant: [.direct("Did you knowingly buy stolen cable?", "\"No. I checked the IDs of everyone who sold me cable, but some gave false names, and I didn't know.\""), .direct("How do you check the sellers?", "\"I copy their driver's license and write the information on a weight ticket. I've done it that way for years.\""), .direct("What did you do when you learned the cable was stolen?", "\"I called deputies, gave them the names on the tickets and let the telecom take back what I still had.\""), .direct("Why was the cable stripped?", "\"A lot of scrap copper comes in stripped. It's common, and I didn't see a reason to be suspicious.\""), .direct("What have you changed since?", "\"I tightened every procedure. I now photograph sellers and the cable and refuse stripped cable without paperwork.\""), .direct("What do you want the court to know?", "\"I'm sorry for the telecom's loss, and I'll help in any way I can.\""), .cross("You have been in this court before about your yard, haven't you?", "\"Yes, and I know I'm responsible for what I buy.\""), .cross("You paid for $18,000 worth of cable, didn't you?", "\"Yes, I paid about that much over several weeks. It was a lot of cable, and I should have asked why the volume kept growing.\""), .cross("The cable was marked with paint, wasn't it?", "\"Some of it was marked with paint, I've been told, and I didn't notice it. I should have looked more carefully at what was coming in.\""), .cross("Sellers gave you false names, didn't they?", "\"Yes, some did, and I didn't catch it. The licenses looked real to me, and I wrote down exactly what they showed.\""), .cross("You didn't call anyone until the telecom came, did you?", "\"No. I had no idea there was a problem until their technician showed me the paint on the cable.\"")],
        openings: ("A telecom depot lost $18,000 worth of cable, and marked cable was found at a scrap yard owned by {D}. Weight tickets match the dates of the thefts, and Court records have {DL} here before, in {PRIORDATE} after being charged with {PRIOR}.", "{DL} says {D.he} checked the IDs of everyone who sold cable, but some gave false names. The defense will show that {D.he} reported the sellers to deputies, and did not know that the cable was stolen."),
        closings: ("Marked cable was found at {D}'s scrap yard, and the weight tickets line up with the depot thefts. The telecom lost $18,000. {DL} was already known to this court from {PRIORDATE} in the file for {PRIOR}. A yard owner is responsible for what {D.he} buys.", "{D} checked IDs, and some sellers gave false names. {DL} reported them to deputies when the problem came to light. The State has not shown that {D} knew the cable was stolen."),
        timeline: [(-20, "The telecom depot starts losing cable to thieves."), (0, "Sellers bring cable to {D}'s scrap yard on the same dates as the thefts."), (7, "The telecom finds marked cable at the yard.")],
        identified: "Weight Tickets",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let poisonAgain = SmallCases.make(
