        role: "Wildlife officer",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a wildlife officer. I enforce hunting and wildlife laws, investigate cruelty to wild animals and respond to injured animals.\""), .direct("How did you learn about this incident?", "\"A member of the public sent me a link to a video of men tormenting a fox pup. It had been posted that morning.\""), .direct("What does the video show?", "\"A group of men, one of whom was filming, cornering a fox pup, poking it with sticks and laughing. The pup was terrified.\""), .direct("Who posted the video?", "\"It was posted from {D}'s account. {DL} also appears at the edge of the frame in a few seconds.\""), .direct("What happened to the pup?", "\"It died the next day from its injuries. A veterinarian said it had been badly stressed and wounded.\""), .direct("What did {DL} say to you?", "\"{D.He} said {D.he} had only been filming and had never touched the pup.\""), .cross("Does the video show {DL} touching the pup?", "\"No. {D.He} is behind the camera most of the time.\""), .cross("Does the video show {DL} telling anyone to stop?", "\"At one point, {D.he} says something like 'that's enough.'\""), .cross("Who else was identified on the video?", "\"Two other men, who have been charged separately.\""), .cross("Did {DL} remove the video?", "\"Yes, after I contacted {D.him}.\""), .cross("Did {DL} cooperate?", "\"Yes. {D.He} gave me names and a statement.\"")],
